<script setup>import {ref} from 'vue';const show=ref(false);const selected=ref({name:'Quantum Drive X-700',sku:'QDX700-BLK',stock:142});const rows=[['MechKey Pro X','KBMPX104',45,12,50,'LOW'],['Quantum Drive 2TB','SSD-Q2NVME',42,30,50,'CRITICAL'],['MeshNet Pro Router','NET-MNPMAX',215,45,50,'OPTIMAL']]</script><template><div><div class="page-head"><div><span class="eyebrow">INVENTORY MANAGEMENT</span><h1>Inventory</h1><p>Manage stock levels across all warehouses and track critical thresholds.</p></div><div><button class="button button-ghost">Export CSV</button><button class="button button-blue">New Product</button></div></div><div class="metrics"><article class="metric-card"><small>ACTIVE SKUS</small><strong>1,248</strong></article><article class="metric-card"><small>LOW STOCK ALERTS</small><strong>2.4%</strong><span>42 needs action</span></article><article class="metric-card"><small>PENDING RESTOCK</small><strong>156</strong><span>units in transit</span></article></div><section class="panel table"><div class="table-row header"><span>PRODUCT & SKU</span><span>AVAILABLE</span><span>RESERVED</span><span>THRESHOLD</span><span>STATUS</span><span>ACTIONS</span></div><div v-for="r in rows" :key="r[1]" class="table-row"><span><b>{{r[0]}}</b><small>SKU: {{r[1]}}</small></span><span>{{r[2]}}</span><span>{{r[3]}}</span><span>{{r[4]}}</span><span><em :class="['status',r[5].toLowerCase()]"><i></i>{{r[5]}}</em></span><button class="text-link" @click="selected={name:r[0],sku:r[1],stock:r[2]};show=true">Adjust Stock</button></div></section><div v-if="show" class="modal-backdrop"><section class="modal"><button class="close" @click="show=false">×</button><span class="eyebrow">STOCK ADJUSTMENT</span><h2>{{selected.name}}</h2><p>SKU: {{selected.sku}} · Current stock {{selected.stock}}</p><label>Adjustment quantity<input type="number" value="0"></label><label>Reason code<select><option>Other</option><option>Damaged</option><option>Correction</option><option>Restock</option></select></label><label>Additional notes<textarea placeholder="Provide context for this adjustment..."></textarea></label><div class="modal-actions"><button class="button button-ghost" @click="show=false">Cancel</button><button class="button button-blue" @click="show=false">Confirm Adjustment</button></div></section></div></div></template>
